/* Las Vegas Raiders DNA — Silver and black. Just win, baby. */
.theme-las-vegas-raiders {
  --bg: oklch(0.154 0 0);
  --surface: oklch(0.209 0 0);
  --surface-2: oklch(0.264 0 0);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.593 0 0);
  --accent: oklch(0.740 0.009 225.1);
  --accent-fg: oklch(0.178 0 0);
  --accent-2: oklch(1.000 0 0);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.25rem;
  --radius-sm: 0.125rem;
  --radius-lg: 0.375rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Graduate", serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.04em;
  --label-transform: uppercase;
  --label-tracking: 0.12em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-las-vegas-raiders h1,
.theme-las-vegas-raiders h2,
.theme-las-vegas-raiders h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-las-vegas-raiders { --font-ui: var(--font-display); }
.theme-las-vegas-raiders h1, .theme-las-vegas-raiders h2 { text-transform: uppercase; }
.theme-las-vegas-raiders h1::after { content: ""; display: block; height: 5px; width: 6rem; margin-top: 0.6rem; background: linear-gradient(90deg, var(--accent) 0 50%, var(--accent-2) 50% 100%); }
.theme-las-vegas-raiders button { text-transform: uppercase; letter-spacing: 0.1em; font-weight: 600; }
.theme-las-vegas-raiders th { color: var(--accent); text-transform: uppercase; letter-spacing: 0.12em; font-size: 11px; border-bottom: 2px solid var(--accent); }
.theme-las-vegas-raiders tbody tr:hover { background: color-mix(in oklab, var(--accent) 8%, transparent); }
.theme-las-vegas-raiders h2 { border-bottom: 3px solid var(--accent); display: inline-block; padding-bottom: 0.15em; }
.theme-las-vegas-raiders ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-las-vegas-raiders h1 { color: #a5acaf; } .theme-las-vegas-raiders button { border: 1px solid #a5acaf; }

/* alt mode: road whites */
.theme-las-vegas-raiders.alt-mode {
  --bg: oklch(0.98 0.001 260); --surface: oklch(1 0 0); --surface-2: oklch(0.94 0.002 260);
  --fg: oklch(0.2 0.005 260); --fg-muted: oklch(0.45 0.005 260); --line: oklch(0.89 0.003 260);
  --accent: oklch(0.45 0.008 225.1); --accent-fg: oklch(1 0 0);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%); --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%); --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: none;
}
.theme-las-vegas-raiders.alt-mode h1 { color: oklch(0.18 0 0); }
.theme-las-vegas-raiders.alt-mode h2, .theme-las-vegas-raiders.alt-mode h3 { color: oklch(0.18 0 0); }
.theme-las-vegas-raiders.alt-mode h1::after { background: linear-gradient(90deg, oklch(0.18 0 0) 0 50%, oklch(0.62 0.008 225.1) 50% 100%); }
.theme-las-vegas-raiders.alt-mode th { color: oklch(0.35 0 0); border-bottom-color: oklch(0.35 0 0); }
.theme-las-vegas-raiders.alt-mode button { border-color: oklch(0.35 0 0); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
